// Package sqlscript reads a SQL script generated by SSMS ("Generate Scripts")
// as a stream of GO-separated batches, without loading the file in memory.
package sqlscript

import (
	"bufio"
	"errors"
	"io"
	"strings"
	"unicode/utf16"
	"unicode/utf8"
)

// ErrNoStatements means the script has nothing to run once the server-level
// header is left out.
var ErrNoStatements = errors.New("el script no contiene sentencias")

// Batch is one GO-separated block of the script.
type Batch struct {
	// Number counts the non-empty batches from 1.
	Number int
	Text   string
	// IsSkipped marks what must not run on an existing database: USE,
	// CREATE DATABASE, ALTER DATABASE and the header between them.
	IsSkipped bool
	// IsPrincipal marks CREATE USER, ALTER ROLE and ALTER AUTHORIZATION. They
	// fail when the login does not exist on this machine: a warning, not an error.
	IsPrincipal bool
}

// NewReader returns the text of the script as UTF-8. It detects the BOM of
// UTF-16 (either order) and UTF-8; without BOM the text is taken as UTF-8.
func NewReader(source io.Reader) (io.Reader, error) {
	reader := bufio.NewReaderSize(source, 64*1024)

	head, err := reader.Peek(3)
	if err != nil && err != io.EOF && err != bufio.ErrBufferFull {
		return nil, err
	}

	switch {
	case len(head) >= 3 && head[0] == 0xEF && head[1] == 0xBB && head[2] == 0xBF:
		reader.Discard(3)
		return reader, nil
	case len(head) >= 2 && head[0] == 0xFF && head[1] == 0xFE:
		reader.Discard(2)
		return &utf16Reader{source: reader}, nil
	case len(head) >= 2 && head[0] == 0xFE && head[1] == 0xFF:
		reader.Discard(2)
		return &utf16Reader{source: reader, isBigEndian: true}, nil
	}

	return reader, nil
}

// utf16Reader converts UTF-16 to UTF-8 as it reads.
type utf16Reader struct {
	source      io.Reader
	isBigEndian bool
	// pending is converted text not yet returned; oddByte and highSurrogate
	// carry what a chunk boundary cut in half.
	pending       []byte
	oddByte       []byte
	highSurrogate uint16
	isDone        bool
}

func (reader *utf16Reader) Read(target []byte) (int, error) {
	for len(reader.pending) == 0 {
		if reader.isDone {
			return 0, io.EOF
		}

		raw := make([]byte, 32*1024)
		count, err := reader.source.Read(raw)
		raw = append(reader.oddByte, raw[:count]...)
		reader.oddByte = nil

		if len(raw)%2 == 1 {
			reader.oddByte = []byte{raw[len(raw)-1]}
			raw = raw[:len(raw)-1]
		}

		units := make([]uint16, 0, len(raw)/2+1)
		if reader.highSurrogate != 0 {
			units = append(units, reader.highSurrogate)
			reader.highSurrogate = 0
		}

		for index := 0; index+1 < len(raw); index += 2 {
			if reader.isBigEndian {
				units = append(units, uint16(raw[index])<<8|uint16(raw[index+1]))
			} else {
				units = append(units, uint16(raw[index])|uint16(raw[index+1])<<8)
			}
		}

		if last := len(units) - 1; last >= 0 && units[last] >= 0xD800 && units[last] < 0xDC00 {
			reader.highSurrogate = units[last]
			units = units[:last]
		}

		for _, char := range utf16.Decode(units) {
			reader.pending = utf8.AppendRune(reader.pending, char)
		}

		if err != nil {
			reader.isDone = true

			if err != io.EOF {
				return 0, err
			}
		}
	}

	count := copy(target, reader.pending)
	reader.pending = reader.pending[count:]

	return count, nil
}

// lexState tracks what a GO line must not be inside of.
type lexState struct {
	isInString       bool
	isInBlockComment bool
	// isInBracket and isInDoubleQuote are quoted identifiers: an apostrophe
	// inside [O'Brien] or "it's" does not open a string.
	isInBracket     bool
	isInDoubleQuote bool
}

// advance moves the state over one line.
func (state *lexState) advance(line string) {
	for index := 0; index < len(line); index++ {
		char := line[index]

		switch {
		case state.isInBlockComment:
			if char == '*' && index+1 < len(line) && line[index+1] == '/' {
				state.isInBlockComment = false
				index++
			}
		case state.isInString:
			if char == '\'' {
				// A doubled quote stays inside the string: toggling twice does the same.
				state.isInString = false
			}
		case state.isInBracket:
			if char == ']' {
				if index+1 < len(line) && line[index+1] == ']' {
					index++ // escaped ]]
				} else {
					state.isInBracket = false
				}
			}
		case state.isInDoubleQuote:
			// A doubled quote closes and reopens on the next character.
			if char == '"' {
				state.isInDoubleQuote = false
			}
		case char == '\'':
			state.isInString = true
		case char == '[':
			state.isInBracket = true
		case char == '"':
			state.isInDoubleQuote = true
		case char == '-' && index+1 < len(line) && line[index+1] == '-':
			return
		case char == '/' && index+1 < len(line) && line[index+1] == '*':
			state.isInBlockComment = true
			index++
		}
	}
}

func isGoLine(line string) bool {
	fields := strings.Fields(line)

	if len(fields) == 0 || len(fields) > 2 || !strings.EqualFold(fields[0], "GO") {
		return false
	}

	if len(fields) == 2 {
		for _, char := range fields[1] {
			if char < '0' || char > '9' {
				return false
			}
		}
	}

	return true
}

// ReadBatches reads the script and calls handle for every non-empty batch, in
// order. It stops at the first error from handle and returns it. A script
// with nothing left to run returns ErrNoStatements.
func ReadBatches(source io.Reader, handle func(Batch) error) error {
	text, err := NewReader(source)
	if err != nil {
		return err
	}

	reader := bufio.NewReaderSize(text, 64*1024)

	var (
		current       strings.Builder
		state         lexState
		number        int
		isInHeader    bool
		hasRunnable   bool
		isEndOfScript bool
	)

	flush := func() error {
		body := current.String()
		current.Reset()

		if strings.TrimSpace(body) == "" {
			return nil
		}

		number++
		batch := Batch{Number: number, Text: body}

		isUse := startsWith(body, "USE")
		isCreateDb := startsWith(body, "CREATE", "DATABASE")
		isAlterDb := startsWith(body, "ALTER", "DATABASE")

		if isCreateDb {
			isInHeader = true
		}

		batch.IsSkipped = isUse || isCreateDb || isAlterDb || isInHeader

		if isUse {
			isInHeader = false
		}

		batch.IsPrincipal = startsWith(body, "CREATE", "USER") ||
			startsWith(body, "ALTER", "ROLE") ||
			startsWith(body, "ALTER", "AUTHORIZATION")

		if !batch.IsSkipped {
			hasRunnable = true
		}

		return handle(batch)
	}

	for !isEndOfScript {
		line, err := reader.ReadString('\n')
		if err != nil {
			if err != io.EOF {
				return err
			}

			isEndOfScript = true
		}

		if line == "" {
			break
		}

		if state == (lexState{}) && isGoLine(line) {
			if err := flush(); err != nil {
				return err
			}

			continue
		}

		state.advance(line)
		current.WriteString(line)
	}

	if err := flush(); err != nil {
		return err
	}

	if !hasRunnable {
		return ErrNoStatements
	}

	return nil
}

// startsWith reports whether the text, after leading comments and blanks,
// begins with the given words (case-insensitive, whole words).
func startsWith(body string, words ...string) bool {
	rest := skipBlanksAndComments(body)

	for _, word := range words {
		rest = strings.TrimLeft(rest, " \t\r\n")

		if len(rest) < len(word) || !strings.EqualFold(rest[:len(word)], word) {
			return false
		}

		rest = rest[len(word):]

		if rest != "" && isWordChar(rest[0]) {
			return false
		}
	}

	return true
}

func isWordChar(char byte) bool {
	return char == '_' || char >= '0' && char <= '9' || char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z'
}

func skipBlanksAndComments(body string) string {
	for {
		body = strings.TrimLeft(body, " \t\r\n")

		switch {
		case strings.HasPrefix(body, "--"):
			end := strings.IndexByte(body, '\n')
			if end < 0 {
				return ""
			}

			body = body[end+1:]
		case strings.HasPrefix(body, "/*"):
			end := strings.Index(body, "*/")
			if end < 0 {
				return ""
			}

			body = body[end+2:]
		default:
			return body
		}
	}
}
